WFI.Data.add("quest", {
  [65597] = { "Il vincolo", "Usando i Lovers' Hearts, evoca e sottometti un incubo, poi riporta i Lovers' Hearts a Carendin Halgar, nel Magic Quarter dell'Undercity.", "Il momento è finalmente arrivato. Porta i cuori al cerchio di evocazione qui sotto. Ponili al centro ed evoca l'incubo.\n\nIl demone non sarà contento quando si accorgerà che l'hai attirato in una trappola. Non cadere vittima delle sue lusinghe, {name}. Devi sottometterlo completamente.\n\nSolo allora potrò insegnarti l'incantesimo per piegarlo alla tua volontà.", nil, nil, 0x5926988f, 0xf62852d5, 0x71f56f10, nil, nil, "...mm" },
  [65603] = { "Il vincolo", "Usando la Wooden Figurine, evoca e sottometti un incubo, poi riporta la Wooden Figurine a Gakin the Darkbinder, allo Slaughtered Lamb.", "Il momento è arrivato. Prendi la statuetta e scendi nelle cripte qui sotto. È stato preparato un cerchio di evocazione, e devi porre la statuetta al centro.\n\nAllora si aprirà il varco e l'incubo passerà nel nostro mondo.\n\nUn sayaad non va sottovalutato. Il demone non esiterà ad attaccare quando capirà il tuo inganno. Devi attingere a tutto ciò che ti è stato insegnato per sconfiggerlo.\n\nSe ci riesci, torna da me e piegherò la creatura alla tua volontà. Se fallisci, la tua anima è perduta.", nil, nil, 0x5926988f, 0x9a339fad, 0xfe44a9e9, nil, nil, "...mm" },
  [65604] = { "Il vincolo", "Usando il Withered Scarf, evoca e sottometti un incubo, poi riporta il Withered Scarf a Gan'rul Bloodeye, a Orgrimmar.", "Sì... capisco. Sento le emozioni residue legate a questi fili. L'amore è intessuto nelle sue cuciture. L'incubo non potrà resistere.\n\nPortalo al cerchio di evocazione nella tenda di Neeru, {name}. Evoca un incubo malevolo, poi mostragli la tua maestria. Non aspettarti che si lasci sottomettere in silenzio. Prepara la tua magia e preparati a combattere. Sottovalutare un demone è stato l'ultimo errore di molti stregoni.\n\nQuando l'avrai sconfitto, riportami la stoffa. Farò sapere a Magar cosa hai trovato.", nil, nil, 0x5926988f, 0x4de62da3, 0xae8e63dd, nil, nil, "...mm" },
})
